  footerSection: { paddingHorizontal: 20, paddingBottom: 20 },
  footer: { alignItems: 'center' },
  footerText: { fontSize: 11, fontWeight: '400', marginBottom: 4, fontFamily: 'Inter' },
  digitalIndiaLogo: { height: 22, width: 100 },
